var msg bytes.Buffer

signature := r.Header.Get("X-Signature-Ed25519")
if signature == "" {
	return false
}

sig, err := hex.DecodeString(signature)
if err != nil {
	return false
}

if len(sig) != ed25519.SignatureSize {
	return false
}

timestamp := r.Header.Get("X-Signature-Timestamp")
if timestamp == "" {
	return false
