if g.VerificationLevel != nil {
	val := *g.VerificationLevel
	if val < 0 || val > 4 {
		err = ErrVerificationLevelBounds
		return
	}
}

// Bounds checking for regions
if g.Region != "" {
	isValid := false
	regions, _ := s.VoiceRegions(options...)
	for _, r := range regions {
